 function captureQueryUI(){
  const popup=document.querySelector('.ap-query [data-ap-dropdown].open'),focus=document.activeElement;
  return {noteOpen:document.querySelector('.ap-calculation-note')?.open,popup:popup?{id:popup.id,search:popup.querySelector('.sf-search-input')?.value||'',dropUp:popup.classList.contains('sf-drop-up'),focus:popup.contains(focus)?{kind:focus.classList.contains('sf-search-input')?'search':focus.matches('input[type=checkbox]')?'option':'trigger',value:focus.value,start:focus.selectionStart,end:focus.selectionEnd}:null}:null};
 }
 async function restoreQueryUI(state,ticket){
  const note=document.querySelector('.ap-calculation-note');if(note)note.open=!!state.noteOpen;
  if(!state.popup)return;const popup=document.getElementById(state.popup.id);if(!popup)return;
  window.SearchableFilterSelects?.scan(popup);popup.classList.add('open');popup.classList.toggle('sf-drop-up',state.popup.dropUp);popup.querySelector('.qf-multi-trigger').setAttribute('aria-expanded','true');
  const search=popup.querySelector('.sf-search-input');if(search){search.value=state.popup.search;search.dispatchEvent(new Event('input',{bubbles:true}));}
  // Let the old dropdown's scheduled focus settle; never steal focus from a new interaction.
  await new Promise(resolve=>setTimeout(resolve,0));
  if(ticket!==loading||currentView!=='academicPublic'||!popup.isConnected||!popup.classList.contains('open')||!state.popup.focus)return;
  const active=document.activeElement;if(active&&active!==document.body&&active!==document.documentElement&&active.isConnected)return;
  const focus=state.popup.focus;let target=focus.kind==='search'?search:focus.kind==='trigger'?popup.querySelector('.qf-multi-trigger'):[...popup.querySelectorAll('input[type=checkbox]')].find(input=>input.value===focus.value&&!input.disabled&&input.getClientRects().length);
  target=target||search;if(target){target.focus({preventScroll:true});if(typeof focus.start==='number'&&target.setSelectionRange)target.setSelectionRange(focus.start,focus.end);}
 }
 async function refresh(){const ticket=++loading;const notice=document.getElementById('ap-error');if(notice)notice.hidden=true;const container=document.getElementById('ap-body');if(container&&!data)container.innerHTML='<div class="card ap-body">正在加载公用版学业数据…</div>';try{const result=await api('/state?'+queryString());if(ticket!==loading||currentView!=='academicPublic')return;if(!periodInitialized){term=result.terms.includes(term)?term:result.defaultTerm||result.terms[0]||'';multiTerms=term?[term]:[];appliedTerms=multiTerms.slice();statStage=result.selection.stage;stageDraft=statStage;periodInitialized=!!term;if(term)return refresh();}const ui=captureQueryUI();data=result;statStage=statStage||result.selection.stage;stageDraft=stageDraft||statStage;selected=new Set([...selected].filter(sid=>data.rows.some(r=>r.sid===sid)));render();await restoreQueryUI(ui,ticket);}catch(e){if(ticket!==loading||currentView!=='academicPublic')return;const node=document.getElementById('ap-body');if(node)node.innerHTML=`<div class="ap-error" role="alert">${esc(errorText(e))}</div>${btn('重试','refresh')}`;}}
