 async function commit(){const d=importDraft;if(!d?.preview)throw Error('请先校验');const accept=!d.preview.counts.errors||document.getElementById('ap-accept')?.checked;if(!accept)throw Error('请明确勾选仅提交有效行，或返回修正');if(d.manual&&(d.preview.counts.errors||(d.editId?d.preview.counts.revised!==1:d.preview.counts.created!==1)))throw Error('没有可以新增的记录，请返回修改');const body={previewId:d.preview.previewId,acceptValid:!!accept,acceptStudentCorrections:!!d.preview.studentCorrections?.length},progress=!d.manual&&window.WorkbenchProgress&&WorkbenchProgress.begin({title:'学业数据导入',message:'正在提交 '+d.preview.counts.valid+' 条有效数据…'});let result;try{if(progress)progress.update(25,'正在写入成绩与预警数据…');result=await api('/commits',body,'POST',{'Idempotency-Key':d.commitId});if(progress)progress.update(85,'正在自动汇总预警和排名…');}catch(e){if(progress)progress.fail('学业数据导入失败：'+(e.message||e));if(e.code==='PREVIEW_STALE'){d.preview=null;if(d.manual)manualForm();else showImport();throw Error('数据已变化，请重新校验预览后再提交');}throw e;}const c=result.counts;try{modal(d.manual?(d.editId?'修订结果':'新增结果'):'导入结果',`<div class="ap-hint">已新增 ${c.created}、修订 ${c.revised}；${c.duplicates} 条重复未写入，${c.skipped} 条未修订，${c.errors} 行错误待处理。批次 ${esc(result.batchId)}</div><p>状态：${esc(result.state)}。自动汇总已更新。</p>`,btn('完成','close')+btn('查看批次','batches'));await refresh();if(progress)progress.succeed('学业数据导入完成：新增 '+c.created+' 条，修订 '+c.revised+' 条');}catch(error){if(progress)progress.fail('学业数据导入后的汇总刷新失败：'+(error.message||error));throw error;}}
