 const defaults={thresholds:[2,3,4,6],enabled:[true,true,true,true],stage:'current',scope:'term',categories:[],rank:'original',passScore:60,cetScore:425,degreeScore:60,absenceFail:false,warningMetric:'courses',creditThresholds:[5,10,15,20],deduplicateCourses:false};
 function ruleCriteria(r){return `<section class="ap-rule-criteria"><b>预警指标与课程统计</b><div class="ap-hint">以下为配置示例，请按本校文件设置；门数或学分指标触发时取最高等级；学业预警与绩点无关，绩点仅用于成绩统计与排名。</div><div class="ap-fields">${selectField('ap-pass-resolution','成绩通过判定',[['everPassed','历史有一次通过即通过（当前默认）'],['latest','所选阶段最后一次成绩作为结论']],r.passResolution||'everPassed')}${selectField('ap-warning-metric','门数 / 学分指标',[['courses','未通过门数'],['credits','未通过学分'],['either','门数或学分（取最高等级）']],r.warningMetric)}${['黄色','橙色','红色','退学'].map((name,i)=>`<label>${name}未通过学分 ≥<input id="ap-credit-${i}" type="number" min="0.01" step="0.01" value="${r.creditThresholds[i]}"></label>`).join('')}</div><label><input type="checkbox" id="ap-deduplicate" ${r.deduplicateCourses?'checked':''}> 跨学期同课程代码只计最近修读学期（无代码的课程分别统计）</label></section>`;}
