 async function rulePreview(){const get=id=>document.getElementById(id),gpa=get('ap-gpa').value.trim();const r={passResolution:get('ap-pass-resolution').value,warningMetric:get('ap-warning-metric').value,creditThresholds:[0,1,2,3].map(i=>Number(get('ap-credit-'+i).value)),deduplicateCourses:get('ap-deduplicate').checked,thresholds:[0,1,2,3].map(i=>Number(get('ap-th-'+i).value)),enabled:[0,1,2,3].map(i=>get('ap-en-'+i).checked),scope:get('ap-scope').value,stage:get('ap-stage').value,rank:get('ap-rank').value,metric:get('ap-metric').value,gradeMap:Object.fromEntries(get('ap-grade-map').value.trim()?get('ap-grade-map').value.split(',').map(x=>{const [k,v]=x.split(':');if(!k||v===undefined)throw Error('等第折算格式应为等第:分数');return [k.trim(),Number(v)];}):[]),categories:get('ap-category').value?[get('ap-category').value]:[],passScore:Number(get('ap-pass').value),cetScore:Number(get('ap-cet').value),degreeScore:Number(get('ap-degree').value),absenceFail:get('ap-absence').checked,gpaMap:gpa?gpa.split(',').map(x=>{const parts=x.split(':');if(parts.length!==2)throw Error('绩点格式应为分数下限:绩点');return {min:Number(parts[0]),point:Number(parts[1])};}):[]};ruleDraft=await api('/rule-preview',{version:data.version,rules:r,...statisticQuery()});modal('确认规则影响',`<p>共有 ${ruleDraft.changes.length} 项等级变化。</p><div class="ap-preview"><table>${ruleDraft.changes.slice(0,100).map(x=>`<tr><td>${esc(x.sid)} ${esc(x.name)}</td><td>${esc(x.term)}</td><td>${esc(x.before)} → ${esc(x.after)}</td></tr>`).join('')}</table></div><div class="ap-hint">历史归档保留原版本，已确认预警的降级/解除仍需复核。</div>`,btn('返回设置','rules')+btn('启用本版本','rule-save','',true));}
