 async function action(name,arg){if(name==='close'){window.closeModal();return;}if(name==='tab'){tab=arg;page=1;selected.clear();render();return;}if(name==='page'){page=Math.max(1,page+Number(arg));render();return;}if(name==='unselect'){selected.clear();render();return;}if(name==='refresh')return refresh();if(name==='import')return importModal(arg);if(name==='read-file')return readFile();if(name==='preview')return preview();if(name==='back-map'){if(importDraft.manual)return manualForm();importDraft.preview=null;showImport();return;}if(name==='commit')return commit();if(name==='detail')return detail(arg);if(name==='rules')return rules();if(name==='rule-preview')return rulePreview();if(name==='rule-save'){await api('/rules',{previewId:ruleDraft.previewId},'PUT');window.closeModal();return refresh();}if(name==='batches')return batches();if(name==='reverse'){const reason=window.prompt('撤销理由（存在后续修订或补考/重修时将阻止撤销）');if(!reason)return;await api('/reversals',{batchId:arg,version:data.version,reason});await refresh();return batches();}if(name==='export')return exportModal();if(name==='export-run')return exportRun();if(name==='case-history')return caseHistory(arg);if(name==='case')return caseModal(arg);if(name==='case-action'){const [id,action]=arg.split('|'),reason=window.prompt('请输入办理说明');if(!reason)return;await api('/case-actions',{id,action,reason,version:data.version});window.closeModal();return refresh();}if(name==='exam-history')return examHistory(arg);if(name==='edit-exam'||name==='edit-attempt')return editRecord(arg,name==='edit-exam');if(name==='manual')return manual(arg);if(name==='manual-preview')return previewManual();if(name==='publish'){if(filterValues.cls.length!==1)throw Error('请先勾选并查询一个要发布的班级');if(!window.confirm('确认本班完整参排名单与课程清单已经核验？缺失记录将阻止发布。'))return;await api('/publications',{term:data.selection.end,cls:filterValues.cls[0],version:data.version,confirmed:true});return refresh();}if(name==='template'){const response=await fetch('/api/academic-public/templates?type='+encodeURIComponent(arg));if(!response.ok){const d=await response.json();throw Error(d.error?.message||'模板下载失败');}const url=URL.createObjectURL(await response.blob()),a=document.createElement('a');a.href=url;a.download='学业情况（公用版）_'+types[arg]+'导入模板.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);return;}if(name==='error-export'){const response=await fetch('/api/academic-public/error-export',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({previewId:importDraft.preview.previewId})});if(!response.ok){const d=await response.json();throw Error(d.error?.message||'下载失败');}const blob=await response.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='学业情况（公用版）_导入错误行.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}}
 const previousAction=action;action=async function(name,arg){
  if(name==='filter'){
   if(!multiTerms.length)throw Error('请至少勾选一个统计学期');
   appliedTerms=multiTerms.slice();statScope=appliedTerms.length===1?'term':'multi';term=appliedTerms.slice().sort().at(-1);statStage=stageDraft;filterDraft.keyword=document.getElementById('ap-keyword').value.trim();filterValues=structuredClone(filterDraft);keyword=filterValues.keyword;selected.clear();page=1;return refresh();
  }
  if(name==='reset'){filterValues=defaultFilters();filterDraft=defaultFilters();keyword='';multiTerms=data.selection.terms.slice();stageDraft=data.selection.stage;selected.clear();page=1;render();return;}
  if(name==='warning-run'){
   const result=await api('/warning-runs',{version:data.version,...statisticQuery(),...filterValues});await refresh();note('名单已生成：预警候选 '+result.counts.warnings+' 人，待核查 '+result.counts.pending+' 人。个案已保存，可进行复核和跟进。','success');return;
  }
  if(name==='run-detail'){
   const {run}=await api('/warning-runs?id='+encodeURIComponent(arg));modal('预警名单生成快照',`<p>${esc(selectionText(run.selection))}</p><div class="ap-hint">${esc(stageNames[run.selection.stage])} · 规则版本 ${run.ruleVersion} · 数据版本 ${run.dataVersion} · ${esc(run.created)}。本页为生成时快照，办理状态以当前个案为准。</div><div class="ap-preview"><table><thead><tr><th>学号</th><th>姓名</th><th>未通过门数</th><th>未通过学分</th><th>预警等级</th><th>触发原因</th></tr></thead><tbody>${run.rows.filter(r=>r.level).map(r=>`<tr><td>${esc(r.sid)}</td><td>${esc(r.name)}</td><td>${r.fail}</td><td>${display(r.failCredit)}</td><td>${esc(r.level)}${r.warningKnown?'':'（待核查）'}</td><td>${r.reasons.map(x=>esc(x.text)).join('；')}</td></tr>`).join('')||'<tr><td colspan="6">本次未触发预警</td></tr>'}</tbody></table></div>`);return;
  }
  if(name==='rule-save'){statStage='';stageDraft='';}
  if(name==='case-batch')return batchModal();
  if(name==='case-batch-preview')return batchPreview();
  if(name==='case-batch-back')return batchForm();
  if(name==='case-batch-commit')return batchCommit();
  if(name==='case-support')return supportModal(arg);
  if(name==='support-save')return supportSave(arg);
  if(name==='case-task'){const result=await api('/case-task',{id:arg,version:data.version});await refresh();note('工作任务已关联：'+result.taskId+'。可在工作任务模块查看。');return;}
  if(name==='publication-export'){const p=data.publications.find(x=>x.id===arg);const result=await api('/exports',{version:data.version,publicationId:arg,term:p.term,kind:'grades'});modal('正式排名文件已生成',`<p>发布时间：${esc(p.created)}，数据版本：${p.version}。</p><a class="btn btn-primary" href="${esc(result.url)}" download>下载正式快照</a>`);return;}
  return previousAction(name,arg);
 };
 function periodFeedback(){const all=document.querySelector('[data-ap-all-periods]'),options=[...document.querySelectorAll('[data-ap-period]')];if(all){all.checked=!!options.length&&multiTerms.length===options.length;all.indeterminate=multiTerms.length>0&&multiTerms.length<options.length;}const count=document.getElementById('ap-period-count');if(count)count.textContent='已选 '+multiTerms.length+' 个学期，点击查询更新结果';}
 document.addEventListener('change',event=>{
  const element=event.target;if(!element.closest('.ap-page'))return;
  if(element.matches('[data-ap-period],[data-ap-all-periods]')){if(element.hasAttribute('data-ap-all-periods'))document.querySelectorAll('[data-ap-period]').forEach(node=>node.checked=element.checked);multiTerms=[...document.querySelectorAll('[data-ap-period]:checked')].map(node=>node.dataset.apPeriod);periodFeedback();refreshDropdown(element.closest('[data-ap-dropdown]'));return;}
  if(element.matches('[data-ap-filter],[data-ap-all]')){const key=element.dataset.apFilter||element.dataset.apAll,group=element.closest('[data-ap-dropdown]');if(element.hasAttribute('data-ap-all'))group.querySelectorAll('[data-ap-filter]').forEach(node=>node.checked=false);filterDraft[key]=[...group.querySelectorAll('[data-ap-filter]:checked')].map(node=>node.value);group.querySelector('[data-ap-all]').checked=!filterDraft[key].length;if(organizationFields.includes(key))cascadeOrganizationFilters();else refreshDropdown(group);return;}
  if(element.matches('[data-ap-stage]')){if(element.checked)stageDraft=element.dataset.apStage;document.querySelectorAll('[data-ap-stage]').forEach(node=>node.checked=node.dataset.apStage===stageDraft);refreshDropdown(element.closest('[data-ap-dropdown]'));return;}
  if(element.id==='ap-select-page'){visibleRows().slice((page-1)*20,page*20).forEach(row=>element.checked?selected.add(row.sid):selected.delete(row.sid));render();return;}
  if(element.matches('[data-ap-select]')){element.checked?selected.add(element.dataset.apSelect):selected.delete(element.dataset.apSelect);const master=document.getElementById('ap-select-page'),rows=visibleRows().slice((page-1)*20,page*20);if(master){const count=rows.filter(r=>selected.has(r.sid)).length;master.checked=!!rows.length&&count===rows.length;master.indeterminate=count>0&&count<rows.length;}const summary=document.getElementById('ap-selection-summary');if(summary){summary.textContent='共 '+summary.dataset.total+' 条 · 第 '+page+'/'+summary.dataset.pages+' 页 · 已选 '+selected.size+' 人';const controls=summary.parentElement.querySelector('div'),clear=controls?.querySelector('[data-ap=unselect]');if(selected.size&&!clear)controls?.insertAdjacentHTML('beforeend',btn('清空选择','unselect'));if(!selected.size&&clear)clear.remove();}return;}
 });
 document.addEventListener('input',event=>{if(event.target.id==='ap-keyword')filterDraft.keyword=event.target.value;});
 document.addEventListener('click',event=>{if(event.target.closest('.qf-multi-trigger,[data-ap-dropdown] input[type=checkbox]'))refreshDropdown(event.target.closest('[data-ap-dropdown]'));});
 document.addEventListener('keydown',event=>{const multi=event.target.closest('[data-ap-dropdown]');if(multi)refreshDropdown(multi);});
 document.addEventListener('keydown',event=>{const multi=event.target.closest('[data-ap-dropdown].open');if(!multi)return;if(event.key==='Escape'){event.preventDefault();event.stopPropagation();multi.classList.remove('open','sf-drop-up');const trigger=multi.querySelector('.qf-multi-trigger');trigger.setAttribute('aria-expanded','false');trigger.focus();return;}if(['ArrowDown','ArrowUp','Home','End'].includes(event.key)&&event.target.matches('input[type=checkbox]')){const choices=[...multi.querySelectorAll('input[type=checkbox]:not(:disabled)')].filter(input=>{const row=input.closest('.qf-multi-opt');return row.style.display!=='none'&&!row.classList.contains('sf-search-hidden');});if(!choices.length)return;const index=choices.indexOf(event.target),next=event.key==='Home'?0:event.key==='End'?choices.length-1:(index+(event.key==='ArrowUp'?-1:1)+choices.length)%choices.length;event.preventDefault();event.stopPropagation();choices[next].focus();}},true);
 window.academicPublicArchiveHTML=function(student){return '<div class="zf-section" style="margin-top:16px">学业情况（公用版）</div><div data-ap-archive="'+esc(student.id)+'" class="ap-hint">正在加载授权范围内的公用版成绩…</div>';};
 window.academicPublicLoadArchive=async function(root){const targets=(root||document.getElementById('modalBody'))?.querySelectorAll('[data-ap-archive]')||[];await Promise.all(Array.from(targets).map(async node=>{if(archiveLoads.has(node))return archiveLoads.get(node);if(node.dataset.apLoaded==='1')return;const pending=(async()=>{node.dataset.apLoaded='loading';try{const result=await api('/student?sid='+encodeURIComponent(node.dataset.apArchive));node.innerHTML='<p>公用版数据版本：'+result.version+'；排名为暂算，个人版另行展示。</p>'+result.rows.map(r=>'<p>'+esc(r.period||r.details[0]?.term||'')+'：未通过 '+r.fail+' 门，待核查 '+r.pending+' 门；加权分 '+display(r.average)+'；班级排名 '+rank(r,'class')+'；专业排名 '+rank(r,'major')+'；'+esc(r.level||(!r.warningKnown?'等级待核查':'未触发'))+'</p>').join('')+result.exams.map(x=>'<p>'+esc(x.type)+' '+esc(x.batch)+' '+esc(x.score??x.official)+' · '+esc(x.result)+'</p>').join('')+(result.rows.length||result.exams.length?'':'暂无公用版记录');}catch(e){node.textContent='公用版数据未加载：'+e.message;}finally{node.dataset.apLoaded='1';}})();archiveLoads.set(node,pending);return pending;}));};
 new MutationObserver(()=>{const root=document.getElementById('modalBody');if(root?.querySelector('[data-ap-archive]:not([data-ap-loaded])'))window.academicPublicLoadArchive(root);}).observe(document.getElementById('modalBody'),{childList:true,subtree:true});
 function indicateActionBusy(){document.querySelectorAll('.ap-page,.ap-modal').forEach(node=>node.setAttribute('aria-busy',String(busy)));}
 document.addEventListener('click',async e=>{const button=e.target.closest('[data-ap]');if(!button||busy)return;e.preventDefault();busy=true;indicateActionBusy();actionContext={modal:button.closest('#modal')?document.querySelector('#modalBody .ap-modal'):null};button.disabled=true;try{await action(button.dataset.ap,button.dataset.arg);}catch(error){if(currentView==='academicPublic')note(errorText(error));}finally{actionContext=null;busy=false;indicateActionBusy();if(button.isConnected)button.disabled=false;}});
 document.addEventListener('change',e=>{const el=e.target;if(el.id==='ap-manual-type'){if(busy){el.value=importDraft.type;return;}importDraft.rows[0]={...importDraft.rows[0],...collectManual()};importDraft.type=el.value;manualForm();return;}if(el.dataset.apEntry==='学号'){manualStudent();return;}if(el.id==='ap-batch-skip'){const button=document.querySelector('[data-ap="case-batch-commit"]');if(button)button.disabled=!el.checked||!batchDraft?.preview?.eligible.length;return;}if(el.id==='ap-mode')importDraft.mode=el.value;if(el.id==='ap-default-batch')importDraft.batch=el.value;if(el.id==='ap-sheet'||el.id==='ap-header'){importDraft.sheet=document.getElementById('ap-sheet').value;importDraft.header=el.id==='ap-sheet'?(importDraft.file.sheets.find(s=>s.name===importDraft.sheet)?.recommendations?.[importDraft.type]?.headerRow||1):Number(document.getElementById('ap-header').value);importDraft.batch=document.getElementById('ap-default-batch')?.value||importDraft.batch;remap();showImport();}if(el.dataset.apMap)importDraft.mapping[el.dataset.apMap]=el.value===''?null:Number(el.value);});
 window.academicPublicSync=function(){const input=document.getElementById('ap-keyword');if(input)filterDraft.keyword=input.value;return refresh();};
